final class MapNavalContractTest {
    private MapNavalContractTest() {}
    private static MapCommanderPanels.Hit hit(String icon){return MapCommanderPanels.hits().stream().filter(h->h.icon().equals(icon)).findFirst().orElseThrow(()->new AssertionError("Missing naval control "+icon));}
    private static void click(net.minecraft.client.Minecraft client,MapCommanderPanels.Hit h,int button){var event=new MouseButtonEvent(h.x()+h.w()/2.,h.y()+h.h()/2.,new MouseButtonInfo(button,0));if(!client.gui.screen().mouseClicked(event,false))throw new AssertionError("Naval input not consumed");client.gui.screen().mouseReleased(event);}
    private static void assessment(Check query,Map<String,Decision> actions){MapCommanderAvailability.accept(new Assessment(query.token(),query.revision(),query.sequence(),query.request(),actions));}
    static void run(ClientGameTestContext game,ProtocolMenuView menu,String directory)throws java.io.IOException{
        var source=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-navy.json"))).view();var reserve=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-navy-patrol-reserve.json"))).view();
        var actions=new Availability(Files.readString(Path.of(directory,"kor-navy-assessment.json"))).assessment().actions();var sea=JsonParser.parseString(Files.readString(Path.of(directory,"kor-sea-tooltips.json"))).getAsJsonObject().entrySet().iterator().next();
        var fleet=source.cards().stream().filter(c->c.name().equals("1st Fleet")).findFirst().orElseThrow();
        var carrierFleet=source.cards().stream().filter(c->c.panel()!=null&&c.panel().members().stream().anyMatch(m->m.data().navy().carrierStance()!=null)).findFirst().orElseThrow();
        var carrier=carrierFleet.panel().members().stream().filter(m->m.data().navy().carrierStance()!=null).findFirst().orElseThrow();
        var carrierActions=new Availability(Files.readString(Path.of(directory,"kor-navy-assessment-carrier.json"))).assessment().actions();
        for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
            var commands=new ArrayList<Command>();var opens=new ArrayList<Open>();var queries=new ArrayList<Check>();var seas=new ArrayList<SeaHover>();var context=new Context[1];
            game.getInput().resizeWindow(size[0],size[1]);
            game.runOnClient(client->{client.options.guiScale().set(2);ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));MapCommanderHud.reset();MapUnitHud.reset();MapCommanderOrders.commandObserver=commands::add;MapCommanderOrders.selectionObserver=q->{};MapCommanderHud.requestObserver=opens::add;MapCommanderAvailability.queryObserver=queries::add;MapCommanderHud.accept(new View(source.country(),client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings(),true));context[0]=new Context(UUID.randomUUID().toString(),1,source.country(),client.level.dimension().identifier().toString(),"");MapCommanderOrders.accept(context[0]);MapCommanderPanels.select(fleet.id(),false);assessment(queries.getLast(),actions);});
            game.setScreen(ScreenMapCursor::new);game.getInput().setCursorPos(size[0]-30,90);game.waitTicks(3);
            game.runOnClient(client->{if(MapCommanderPanels.hits().stream().filter(h->h.icon().startsWith("naval_tool_")).count()!=12)throw new AssertionError("Twelve tools must remain after hiding three unsupported or unverified controls");if(!hit("naval_mission_PATROL").tip().equals(actions.get("NAVY/PATROL").details()))throw new AssertionError("Mission tooltip must preserve the complete server text and shortcut");if(!hit("naval_home_base").tip().equals(fleet.panel().fleet().homeBaseTooltip()))throw new AssertionError("Home tooltip must preserve source text");if(!MapCommanderPanels.hits().stream().anyMatch(h->h.tip().equals(fleet.panel().members().getFirst().data().navy().activityTooltip())))throw new AssertionError("Activity tooltip must be authoritative");});
            game.runOnClient(client->{for(String tool:List.of("CREATE","SELECT_HALF","UPGRADE"))if(MapCommanderPanels.hits().stream().anyMatch(h->h.icon().equals("naval_tool_"+tool)))throw new AssertionError("Hidden tool must have no clickable hit region");var text=hit("naval_mission_PATROL").tip();for(String kind:List.of("SPEED","SURFACE_VISIBILITY")){String paragraph=dev.hoi.client.ui.UiCommandLabels.text("NAVAL_MISSION_MISSED_REQUIREMENT_WARN_"+kind+"_DESC","");if(paragraph.isEmpty()||!text.contains(paragraph))throw new AssertionError("Patrol must include original warning explanation: "+kind);}if(!hit("naval_dominance").tip().equals(fleet.panel().members().getFirst().data().navy().dominanceTooltip()))throw new AssertionError("Dominance tooltip must be authoritative");if(!hit("naval_fuel").tip().equals(MapCommanderAirBases.fuelTooltip(source.country())))throw new AssertionError("Fuel must use the national snapshot");for(var member:fleet.panel().members())if(member.data().navy().activityIcon().equals("ship_activity_docked")&&!MapCommanderPanels.navalActivityIcon(member).equals("commander/commands/nv_all_missions/frame_0"))throw new AssertionError("Docked forces must use the copper mission anchor");});
            game.takeScreenshot("hoi-navy-contract-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{var disabled=new HashMap<>(actions);disabled.put("NAVY/STRIKE_FORCE",new Decision(false,false,"선택한 태스크 포스는 타격 임무를 수행할 수 없습니다.","",false));assessment(queries.getLast(),disabled);});game.waitTicks(2);
            game.takeScreenshot("hoi-navy-strike-disabled-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{for(int button:List.of(InputConstants.MOUSE_BUTTON_LEFT,InputConstants.MOUSE_BUTTON_LEFT,InputConstants.MOUSE_BUTTON_RIGHT))click(client,hit("naval_mission_STRIKE_FORCE"),button);if(!commands.isEmpty()||!opens.isEmpty()||!hit("naval_mission_STRIKE_FORCE").tip().contains("타격 임무를 수행할 수 없습니다."))throw new AssertionError("Disabled strike must preserve reason and never send on repeated or right clicks");assessment(queries.getLast(),actions);});game.waitTicks(2);
            var patrol=game.computeOnClient(client->hit("naval_mission_PATROL"));game.getInput().setCursorPos((patrol.x()+patrol.w()/2)*2,(patrol.y()+patrol.h()/2)*2);game.waitTicks(2);game.takeScreenshot("hoi-navy-contract-patrol-tooltip-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{if(actions.get("NAVAL_TB/UNDERWAY").enabled())throw new AssertionError("Fixture must retain unsupported action boundaries");click(client,hit("naval_tool_UNDERWAY"),InputConstants.MOUSE_BUTTON_LEFT);if(MapCommanderPanels.hits().stream().anyMatch(h->h.icon().equals("naval_tool_STANCE"))||!hit("naval_tool_REPAIR_CANCEL").tip().equals(actions.get("NAVAL_TB/REPAIR_CANCEL").details()))throw new AssertionError("Non-carriers must display repair cancellation with exact server text");if(!commands.isEmpty()||!opens.isEmpty())throw new AssertionError("Disabled tools cannot send requests");click(client,hit("naval_tool_REINFORCE"),InputConstants.MOUSE_BUTTON_LEFT);click(client,hit("naval_tool_REINFORCE"),InputConstants.MOUSE_BUTTON_LEFT);if(commands.size()!=1||!commands.getFirst().action().equals("NAVAL_SETTING/BATCH/REINFORCE")||!commands.getFirst().selection().equals(MapCommanderPanels.navalBatch(fleet.panel().members(),"REINFORCE")))throw new AssertionError("Reinforce must send one bounded batch with every expected state");});
            game.runOnClient(client->{MapCommanderOrders.accept(new Context(context[0].token(),2,context[0].country(),context[0].dimension(),""));assessment(queries.getLast(),actions);});game.waitTicks(2);
            game.runOnClient(client->{click(client,hit("naval_tool_AGGRESSIVENESS"),InputConstants.MOUSE_BUTTON_RIGHT);if(commands.size()!=2||!commands.getLast().action().equals("NAVAL_SETTING/BATCH/ENGAGEMENT_PREVIOUS"))throw new AssertionError("Right-click must cycle the selected batch backwards");MapCommanderOrders.accept(new Context(context[0].token(),3,context[0].country(),context[0].dimension(),""));assessment(queries.getLast(),actions);});game.waitTicks(2);
            game.runOnClient(client->{click(client,hit("naval_tool_DELETE"),InputConstants.MOUSE_BUTTON_RIGHT);if(!opens.isEmpty())throw new AssertionError("Delete right-click must not open confirmation");click(client,hit("naval_tool_DELETE"),InputConstants.MOUSE_BUTTON_LEFT);if(opens.size()!=1||opens.getFirst().mode()!=Mode.NAVAL_ORGANIZE||!opens.getFirst().target().equals("DELETE"))throw new AssertionError("Delete must open the server confirmation");click(client,hit("naval_insignia"),InputConstants.MOUSE_BUTTON_LEFT);});game.waitTicks(2);
            game.getInput().setCursorPos(size[0]-30,150);game.waitTicks(2);game.takeScreenshot("hoi-navy-color-picker-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{var color=MapCommanderHud.boxes().stream().filter(b->b.tip().startsWith("함대 색상 #")).findFirst().orElseThrow();MapCommanderHud.clickAt(color.x()+color.width()/2.,color.y()+color.height()/2.);if(!commands.getLast().action().equals("FLEET_COLOR")||!commands.getLast().selection().getFirst().equals(fleet.id()))throw new AssertionError("Fleet palette must use the fleet command");MapCommanderOrders.accept(new Context(context[0].token(),4,context[0].country(),context[0].dimension(),""));assessment(queries.getLast(),actions);var old=queries.getLast();MapCommanderPanels.select(fleet.id(),true);assessment(old,actions);if(MapCommanderAvailability.reason("NAVAL_TB/REINFORCE").isEmpty())throw new AssertionError("Old selection assessment must be rejected");MapCommanderHud.accept(new View(reserve.country(),client.level.dimension().identifier().toString(),reserve.branch(),reserve.cards(),reserve.wings(),true));MapCommanderPanels.select(fleet.id(),false);MapCommanderAvailability.queryObserver=null;MapCommanderAvailability.reset();});game.waitTicks(2);
            game.runOnClient(client->{var last=reserve.cards().getLast();if(last.role()!=Mode.NAVY_HQ||!last.panel().fleet().reserve()||MapCommanderCardDrag.siblings(reserve,reserve.cards().getFirst(),"").contains(last))throw new AssertionError("Reserve card must remain last and outside reordering");});
            game.getInput().setCursorPos(size[0]-30,90);game.waitTicks(2);game.takeScreenshot("hoi-navy-patrol-reserve-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{MapNavalSeaHover.queryObserver=seas::add;MapNavalSeaHover.point(new Ray(0,-1,0),Vec3.ZERO,"test");MapNavalSeaHover.tick();var first=seas.getLast();MapNavalSeaHover.point(new Ray(.1,-Math.sqrt(.99),0),Vec3.ZERO,"test");MapNavalSeaHover.accept(new SeaHoverTooltip(first.sequence(),sea.getKey(),sea.getValue().getAsString()));if(!MapNavalSeaHover.text().isEmpty())throw new AssertionError("Moved cursor must reject stale response");for(int n=0;n<4;n++)MapNavalSeaHover.tick();if(seas.size()<2)throw new AssertionError("Stationary cursor must retry a discarded query");var latest=seas.getLast();MapNavalSeaHover.accept(new SeaHoverTooltip(latest.sequence(),sea.getKey(),sea.getValue().getAsString()));if(!MapNavalSeaHover.text().equals(sea.getValue().getAsString()))throw new AssertionError("Sea text must remain exact");MapNavalSeaHover.accept(new SeaHoverTooltip(latest.sequence(),"",""));if(!MapNavalSeaHover.text().isEmpty())throw new AssertionError("Land reply must clear the tooltip");MapNavalSeaHover.reset();client.player.setXRot(75);client.player.xRotO=75;MapNavalSeaHover.queryObserver=q->MapNavalSeaHover.accept(new SeaHoverTooltip(q.sequence(),sea.getKey(),sea.getValue().getAsString()));});
            game.getInput().setCursorPos(size[0]*.65,size[1]*.45);game.waitTicks(6);game.runOnClient(client->{if(MapNavalSeaHover.text().isEmpty())throw new AssertionError("Actual camera ray must request the sea tooltip");});game.takeScreenshot("hoi-navy-sea-tooltip-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{MapNavalSeaHover.queryObserver=null;MapNavalSeaHover.reset();MapCommanderHud.reset();MapCommanderAvailability.queryObserver=queries::add;MapCommanderHud.accept(new View(source.country(),client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings(),true));context[0]=new Context(UUID.randomUUID().toString(),10,source.country(),client.level.dimension().identifier().toString(),"");MapCommanderOrders.accept(context[0]);MapCommanderPanels.select(fleet.id(),false);assessment(queries.getLast(),actions);commands.clear();opens.clear();});game.getInput().setCursorPos(size[0]-30,90);game.waitTicks(2);
            game.runOnClient(client->{click(client,hit("naval_tool_REPAIR_CANCEL"),InputConstants.MOUSE_BUTTON_RIGHT);if(!commands.isEmpty())throw new AssertionError("Repair cancel right-click must do nothing");click(client,hit("naval_tool_REPAIR_CANCEL"),InputConstants.MOUSE_BUTTON_LEFT);click(client,hit("naval_tool_REPAIR_CANCEL"),InputConstants.MOUSE_BUTTON_LEFT);if(commands.size()!=1||!commands.getFirst().action().equals("NAVAL_SETTING/REPAIR_CANCEL_BATCH")||!commands.getFirst().selection().equals(fleet.panel().members().stream().map(Member::id).toList()))throw new AssertionError("Repair cancel must target the selected forces once");MapCommanderOrders.accept(new Context(context[0].token(),11,context[0].country(),context[0].dimension(),""));MapCommanderPanels.select(carrierFleet.id(),false);});game.waitTicks(2);
            game.runOnClient(client->{var band=MapCommanderPanels.hits().stream().filter(h->h.icon().equals("naval_force_band")&&h.tip().startsWith(carrier.name()+"\n")).findFirst().orElseThrow();click(client,band,InputConstants.MOUSE_BUTTON_LEFT);assessment(queries.getLast(),carrierActions);});game.waitTicks(2);
            game.runOnClient(client->{if(!MapCommanderPanels.commandSelection().equals(List.of("navy/"+carrier.id()))||!Objects.equals(MapCommanderPanels.navalStance(List.of(carrier)),2)||!hit("naval_tool_STANCE").tip().equals(carrierActions.get("NAVAL_TB/STANCE").details())||MapCommanderPanels.hits().stream().anyMatch(h->h.icon().equals("naval_tool_REPAIR_CANCEL")))throw new AssertionError("Carrier selection must replace cancel with authoritative balanced stance");for(var member:fleet.panel().members())if(!member.data().navy().hullStrength().keySet().containsAll(member.composition().keySet())||!member.data().navy().hullOrganization().keySet().containsAll(member.composition().keySet())||member.data().navy().repairPolicy()==null)throw new AssertionError("Fixture must supply real per-hull ratios and repair policy");});
            game.runOnClient(client->{if(!Objects.equals(carrierFleet.panel().fleet().hullAir().get("unit_hud/navy_carrier"),0.0)||!Objects.equals(carrier.data().navy().hullAir().get("unit_hud/navy_carrier"),0.0)||!fleet.panel().fleet().hullAir().isEmpty())throw new AssertionError("Authoritative aircraft ratio must be zero for this empty carrier and absent for non-carriers");});
            game.takeScreenshot("hoi-navy-carrier-stance-"+size[0]+"x"+size[1]+"-gui2");
            var stance=game.computeOnClient(client->hit("naval_tool_STANCE"));game.getInput().setCursorPos((stance.x()+stance.w()/2)*2,(stance.y()+stance.h()/2)*2);game.waitTicks(2);game.takeScreenshot("hoi-navy-carrier-stance-tooltip-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{click(client,hit("naval_tool_STANCE"),InputConstants.MOUSE_BUTTON_LEFT);click(client,hit("naval_tool_STANCE"),InputConstants.MOUSE_BUTTON_RIGHT);if(commands.size()!=2||!commands.getLast().action().equals("NAVAL_SETTING/BATCH/STANCE_NEXT")||!commands.getLast().selection().equals(List.of(carrier.id(),"0/stance/2")))throw new AssertionError("Carrier left click must send one exact batch pending acknowledgement");MapCommanderOrders.accept(new Context(context[0].token(),12,context[0].country(),context[0].dimension(),""));assessment(queries.getLast(),carrierActions);});game.waitTicks(2);
            game.runOnClient(client->{click(client,hit("naval_tool_STANCE"),InputConstants.MOUSE_BUTTON_RIGHT);if(commands.size()!=3||!commands.getLast().action().equals("NAVAL_SETTING/BATCH/STANCE_PREVIOUS")||!commands.getLast().selection().equals(List.of(carrier.id(),"0/stance/2"))||!opens.isEmpty())throw new AssertionError("Carrier right click must cycle backwards without a modal");});
            for(String state:List.of("on-half","off-empty","unknown")){
                var synthetic=JsonParser.parseString(Files.readString(Path.of(directory,"kor-command-panel-navy.json"))).getAsJsonObject();
                for(var element:synthetic.getAsJsonArray("cards")){var card=element.getAsJsonObject();if(!card.get("id").getAsString().equals(carrierFleet.id()))continue;var panel=card.getAsJsonObject("panel");var air=panel.getAsJsonObject("fleet").getAsJsonObject("hullAir");if(state.equals("unknown"))air.remove("unit_hud/navy_carrier");else air.addProperty("unit_hud/navy_carrier",state.equals("on-half")?.5:0);for(var member:panel.getAsJsonArray("members")){var navy=member.getAsJsonObject().getAsJsonObject("data").getAsJsonObject("navy");if(state.equals("unknown"))navy.remove("autoSplit");else navy.addProperty("autoSplit",state.equals("on-half"));var hullAir=navy.getAsJsonObject("hullAir");if(hullAir.has("unit_hud/navy_carrier")){if(state.equals("unknown"))hullAir.remove("unit_hud/navy_carrier");else hullAir.addProperty("unit_hud/navy_carrier",state.equals("on-half")?.5:0);}}}
                var variant=new Snapshot(synthetic.toString()).view();game.runOnClient(client->{MapCommanderHud.accept(new View(variant.country(),client.level.dimension().identifier().toString(),variant.branch(),variant.cards(),variant.wings(),true));});game.getInput().setCursorPos(size[0]-30,90);game.waitTicks(2);game.takeScreenshot("hoi-navy-synthetic-air-split-"+state+"-"+size[0]+"x"+size[1]+"-gui2");
            }
            for(String state:List.of("off","mixed","all")){
                var synthetic=JsonParser.parseString(Files.readString(Path.of(directory,"kor-command-panel-navy.json"))).getAsJsonObject();
                for(var element:synthetic.getAsJsonArray("cards")){var card=element.getAsJsonObject();if(!card.get("id").getAsString().equals(fleet.id()))continue;int index=0;for(var member:card.getAsJsonObject("panel").getAsJsonArray("members")){member.getAsJsonObject().addProperty("mission",state.equals("all")||state.equals("mixed")&&index==0?"STRIKE_FORCE":"HOLD");index++;}if(index<2)throw new AssertionError("Mixed strike fixture requires multiple task forces");}
                var variant=new Snapshot(synthetic.toString()).view();game.runOnClient(client->{MapCommanderHud.reset();MapUnitHud.reset();MapCommanderHud.accept(new View(variant.country(),client.level.dimension().identifier().toString(),variant.branch(),variant.cards(),variant.wings(),true));MapCommanderOrders.accept(new Context(UUID.randomUUID().toString(),20,variant.country(),client.level.dimension().identifier().toString(),""));MapCommanderPanels.select(fleet.id(),false);var enabled=new HashMap<>(actions);enabled.put("NAVY/STRIKE_FORCE",new Decision(true,false,"","",false));assessment(queries.getLast(),enabled);if(!MapCommanderAvailability.reason("NAVY/STRIKE_FORCE").isEmpty())throw new AssertionError("Synthetic strike scenario must receive an enabled assessment");});game.getInput().setCursorPos(size[0]-30,90);game.waitTicks(2);game.takeScreenshot("hoi-navy-synthetic-strike-"+state+"-"+size[0]+"x"+size[1]+"-gui2");
            }
            game.runOnClient(client->{MapCommanderAvailability.queryObserver=null;MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;MapCommanderHud.requestObserver=null;MapNavalSeaHover.queryObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});
        }
    }
}
